.lsb-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsb-root,.lsb-root *,.lsb-root *::before,.lsb-root *::after{box-sizing:border-box}
.lsb-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsb-root img{display:block;border:0;max-width:none}
.lsb-root [hidden]{display:none!important}
.lsb-root .nS6_124_1964{position:absolute;align-content:stretch;display:flex;height:38px;align-items:center;justify-content:space-between;left:0;padding-left:12px;top:0;width:842px;border-style:solid;border-color:var(--wa-line, #6c7688);border-width:1px;background-image:linear-gradient(-18.318853114226968deg, color-mix(in srgb, var(--wa-surface, rgb(137 150 173)) 1.2%, transparent) 45.898%, color-mix(in srgb, var(--wa-surface, rgb(137 150 173)) 20%, transparent) 45.898%), linear-gradient(90deg, color-mix(in srgb, var(--wa-bg, rgb(3 5 12)) 90%, transparent) 0%, color-mix(in srgb, var(--wa-bg, rgb(3 5 12)) 90%, transparent) 100%)}
.lsb-root .nS6_124_1965{align-content:stretch;display:flex;align-items:center;position:relative;flex-shrink:0}
.lsb-root .nS6_124_1966{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:19px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #f8f8f8);font-size:16px;white-space:nowrap;width:152px}
.lsb-root .nS6_124_1967{align-content:stretch;display:flex;flex-direction:column;height:27.335px;align-items:center;justify-content:center;position:relative;border-bottom-left-radius:7px;border-top-left-radius:7px;flex-shrink:0;width:31.685px;background-image:linear-gradient(90deg, var(--wa-point, rgb(40, 97, 255)) 0%, var(--wa-point, rgb(69, 93, 219)) 100%), linear-gradient(90deg, var(--wa-surface, rgb(217, 217, 217)) 0%, var(--wa-surface, rgb(217, 217, 217)) 100%)}
.lsb-root .nS6_124_1968{position:relative;flex-shrink:0;width:12px;height:12px}
.lsb-root .x600024{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsb-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsb-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsb-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.lsb-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsb-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsb-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsb-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsb-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsb-root[data-theme="light"] .nS6_124_1964{border-color:var(--wa-line, #9ca0a9);background-image:linear-gradient(-18.318853114226968deg, color-mix(in srgb, var(--wa-surface, rgb(137 150 173)) 1.2%, transparent) 45.898%, color-mix(in srgb, var(--wa-surface, rgb(137 150 173)) 20%, transparent) 45.898%), linear-gradient(90deg, color-mix(in srgb, var(--wa-point, rgb(217 221 235)) 90%, transparent) 0%, color-mix(in srgb, var(--wa-point, rgb(217 221 235)) 90%, transparent) 100%)}
.lsb-root[data-theme="light"] .nS6_124_1966{color:var(--wa-text, #141517)}
.lsb-root[data-theme="light"] .nS6_124_1967{background-image:linear-gradient(90deg, var(--wa-point, rgb(40, 97, 255)) 0%, var(--wa-point, rgb(69, 93, 219)) 100%), linear-gradient(90deg, var(--wa-surface, #707681) 0%, var(--wa-surface, #707681) 100%)}
